                      <span style={{ color: UI.ink3, fontWeight: 500 }}>
                        크레딧 <span style={{ fontFamily: UI.mono, fontVariantNumeric: "tabular-nums", color: UI.ink2 }}>{usage.credits.toLocaleString()}</span>개
                      </span>
